$string['settings_support_heading'] = 'Escalado a soporte';
$string['settings_support_heading_desc'] = 'Cuando el asistente de soporte no puede resolver una consulta, puede ofrecer al participante enviarla al equipo de soporte. El participante confirma siempre con un clic explícito, y es Moodle —nunca el proveedor de IA— quien añade su nombre, su correo y su curso al mensaje. Estos valores son los predeterminados de todo el sitio; cada curso puede modificarlos.';
$string['settings_support_include_transcript'] = 'Incluir la conversación';
